#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 vector<vector<int>> findWinners(vector<vector<int>>& matches){map<int,int> loss;for(auto&m:matches){loss.emplace(m[0],0);++loss[m[1]];}
  vector<vector<int>>ans(2);for(auto&kv:loss){if(kv.second==0)ans[0].push_back(kv.first);if(kv.second==1)ans[1].push_back(kv.first);}return ans;
 }
};
